{
  "status": "issues",
  "checks": [
    "claim_scope",
    "numeric_bounds"
  ],
  "issues": [
    {
      "category": "scope_expansion",
      "claim_path": "/chapter_plan/units/2/paragraph_briefs/1/development",
      "claim_quote": "利用 P0002 的数值分析结果（图 2d/2e）论证，在掠射角（grazing angles）附近，光线穿过透镜的有效光程差变化率降低，导致所需的相位调制范围反而减小。",
      "problem": "主张中明确引用了 P0002 的“图 2d/2e”作为证据，但提供的 source_materials 和 tool_materials 中仅包含该论文的文字摘要、解释性段落和定性描述（如“如图 2d 和 2e 所示”的转述），并未包含实际的图表图像或图中具体的数值数据点。计划声称“利用...结果...论证”，暗示直接使用了图表数据，而现有材料仅支持对该现象的定性复述，无法支撑对具体图表数据的直接引用或定量论证。",
      "requested_change": "修改表述，移除对具体图表编号（图 2d/2e）的直接引用，改为引用文中对该现象的定性描述或理论推导结论，除非能获取包含实际图表数据的全文材料。",
      "evidence": [
        {
          "path": "/source_materials/1/deep_read_material/question_material/0/examples/0/finding",
          "quote": "对于有限横向尺度的金属透镜，所需的总相位范围（即归一化群延迟范围）并不随入射角 α 单调增加。在掠射角（grazing angles）附近，所需相位范围最小；而在某个特定角度达到最大值，该角度取决于金属透镜的最大半径 R。"
        },
        {
          "path": "/source_materials/1/deep_read_material/question_material/1/explanation",
          "quote": "如图 2d 和 2e 所示，对于给定的入射角α，透镜表面上各点所需的相位值不同。随着入射角α从 0 增加到 90 度（掠射角），透镜上所需的相位范围（最大值与最小值之差）并不是单调增加的。"
        }
      ]
    },
    {
      "category": "numeric_bound",
      "claim_path": "/chapter_plan/units/2/paragraph_briefs/2/development",
      "claim_quote": "基于上述非单调性，解释当工作视场角 α0 小于临界角 α* 时，增大 FOV 会压缩带宽；但一旦 α0 > α*，继续增大 FOV 所引入的新角度对应的群延迟范围小于 α* 处的值，因此整个透镜面上的 ΔT_max 被锁定在 α* 处的极值，导致带宽下限停止收紧并趋于饱和。",
      "problem": "主张中使用了严格的逻辑不等式关系（α0 < α* 和 α0 > α*）来描述带宽饱和的临界条件。然而，提供的 P0002 材料明确指出“文中未明确给出带宽饱和发生的具体临界 FOV 解析表达式，仅通过数值计算展示其存在”以及“未提供计算临界FOV的具体解析公式”。虽然定性趋势支持饱和现象，但材料中缺乏定义该临界角 α* 的具体数值边界或解析条件，使得主张中的精确不等式逻辑缺乏直接的数值证据支持，属于过度精确化的推断。",
      "requested_change": "软化关于临界角 α* 的精确不等式表述，强调这是基于数值观察到的定性趋势，并补充说明目前缺乏解析表达式来确定具体的临界角度值。",
      "evidence": [
        {
          "path": "/source_materials/1/deep_read_material/question_material/0/explanation",
          "quote": "文中未明确给出带宽饱和发生的具体临界 FOV 解析表达式，仅通过数值计算展示其存在。"
        },
        {
          "path": "/source_materials/1/deep_read_material/question_material/1/explanation",
          "quote": "文中未提供计算临界 FOV 的具体解析公式，仅指出其依赖于 NA 和焦点定义。"
        }
      ]
    },
    {
      "category": "scope_expansion",
      "claim_path": "/chapter_plan/units/2/substantive_point",
      "claim_quote": "揭示有限孔径金属透镜上群延迟需求的非单调性特征，论证由此产生的“带宽饱和”现象及其物理根源。",
      "problem": "主张断言揭示了“物理根源”，但提供的 P0002 材料多次强调该结论基于“标量相位近似”和“局部相互作用假设”，且明确指出“未详细讨论矢量衍射效应对该标量相位模型推导的带宽界限的具体修正影响”。在缺乏对矢量效应或非局部效应验证的情况下，将基于特定近似模型的结果宣称为普遍的“物理根源”可能超出了材料的支持范围，忽略了模型假设带来的局限性。",
      "requested_change": "在论述物理根源时，明确限定该结论是在“标量近似”和“局部相互作用假设”下的理论结果，并提及矢量衍射效应可能带来的修正尚未在本材料中量化。",
      "evidence": [
        {
          "path": "/source_materials/1/study_summary_A/contribution_and_limits/1/limits",
          "quote": "所给摘要未交代具体的数值验证案例或实验数据对比；理论假设基于局部相互作用的一维延迟线模型，未考虑非局域效应或多层结构带来的潜在突破可能。"
        },
        {
          "path": "/source_materials/1/deep_read_material/question_material/0/explanation",
          "quote": "未详细讨论矢量衍射效应对该标量相位模型推导的带宽界限的具体修正影响，主要基于几何光学和局部相位近似。"
        }
      ]
    }
  ]
}

